const diamondNumber=n=>Number(n||0).toLocaleString('ko-KR',{maximumFractionDigits:5});
function diamondWalletHTML(w,cash=true){
 if(!w)return '';
 const p=w.partner;
 return `<section class="surface diamond-wallet"><div class="diamond-wallet-head"><div><span class="eyebrow">사용 가능한 다이아</span><h2>◇ ${diamondNumber(w.available)} <small>다이아</small></h2><p>세전 ${number(w.cash_value_krw)}원 · 1다이아 = 100원 = 10골드</p></div><span class="partner-badge">${p.tier==='partner'?'✓ 공식 파트너':'일반 창작자'}</span></div><p class="field-help">월 마감 후 확정된 수익만 사용할 수 있어요. 작은 선물의 소수점 수익도 계속 누적돼요. 골드는 현금 정산할 수 없어요.</p>${w.balance<0?'<p class="form-error">환불·제외된 수익으로 잔액 조정이 필요해요.</p>':''}<div class="diamond-actions"><form id="diamond-exchange-form" class="upload-form" data-available="${Math.floor(w.available)}"><h3>다이아로 골드 전환</h3><label class="form-field">사용할 다이아<input name="diamonds" type="number" min="1" max="${Math.floor(w.available)}" step="1" value="50" required></label><p class="diamond-preview">50다이아 → 500골드</p><button class="primary-button" ${w.available<1?'disabled':''}>골드로 전환</button><p class="form-error" role="alert"></p><small>추가 차감 없음 · 전환한 골드로 다른 사람에게 선물할 수 있어요. 전환은 되돌릴 수 없어요.</small></form>${cash?`<form id="diamond-payout-form" class="upload-form"><h3>다이아 현금 정산</h3><label class="form-field">정산할 다이아<input name="diamonds" type="number" min="${w.min_payout_diamonds}" max="${Math.floor(w.available)}" step="1" value="${w.min_payout_diamonds}" required></label><p class="diamond-preview"></p><button class="small-button" ${w.available<w.min_payout_diamonds?'disabled':''}>현금 정산 신청</button><p class="form-error" role="alert"></p><small>${w.min_payout_diamonds}다이아부터 월 1회 신청 · 신청 다음 달 25일 지급 예정 · 계좌 등록 필요 · 별도 환전 수수료 없음</small></form>`:'<a class="small-button" href="#payouts">다이아 내역 · 현금 정산</a>'}</div><p class="field-help">파트너 인정 실적 ${number(p.eligible_krw)}원 / 1,000,000원${p.review_required?' · 조건 달성, 운영자 검증 대기':''}. 골드 전환이나 현금 정산으로 사용해도 누적 실적은 줄지 않아요.</p></section>`;
}
function diamondHistoryHTML(w){const labels={gift:'선물 수익 확정',stream:'재생 수익 확정',exchange:'골드 전환',payout:'현금 정산 신청',reverse:'수익 제외'};return w?.history?.length?section('다이아 내역')+`<div class="surface gift-history">${w.history.map(r=>`<div class="gift-row"><span>${labels[r.kind]||esc(r.kind)}<small>${esc(r.detail)} · ${esc(r.period)}</small></span><strong>${r.diamonds>0?'+':''}${diamondNumber(r.diamonds)} ◇${r.gold?' → '+number(r.gold)+' G':''}</strong><time>${new Date(r.created*1000).toLocaleDateString('ko-KR')}</time></div>`).join('')}</div>`:'';}
function bindDiamondForms(){
 for(const kind of ['exchange','payout']){
  const form=document.getElementById('diamond-'+kind+'-form');if(!form)continue;
  const input=form.elements.diamonds,preview=form.querySelector('.diamond-preview');
  const show=()=>{const n=Number(input.value)||0,gross=n*100,tax=AifectGifts.withholding(gross);preview.textContent=kind==='exchange'?`${diamondNumber(n)}다이아 → ${number(n*10)}골드`:`세전 ${number(gross)}원 − 원천징수 ${number(tax.income+tax.local)}원 = 예상 지급 ${number(tax.net)}원`;};input.oninput=show;show();
  let requestId=crypto.randomUUID(),lastAmount=null;
  form.onsubmit=busyForm(form,async fd=>{const diamonds=Number(fd.get('diamonds'));if(diamonds!==lastAmount){requestId=crypto.randomUUID();lastAmount=diamonds;}if(!confirm(preview.textContent+'\n'+(kind==='exchange'?'골드 전환은 되돌릴 수 없어요. 전환할까요?':'이 금액으로 현금 정산을 신청할까요?')))return;await api('/api/diamonds/'+kind,'POST',{diamonds,request_id:requestId});requestId=crypto.randomUUID();toast(kind==='exchange'?'골드로 전환했어요. 이제 선물할 수 있어요.':'다이아 정산을 신청했어요.');await render();});
 }
 const exclude=document.getElementById('gift-exclude-form');if(exclude)exclude.onsubmit=busyForm(exclude,async fd=>{if(!confirm('선물 실적을 제외하고 확정 다이아를 회수할까요?'))return;await api('/api/admin/diamonds/exclude-gift','POST',Object.fromEntries(fd));toast('선물 수익을 제외했어요.');await render();});
 const partner=document.getElementById('partner-review-form');if(partner)partner.onsubmit=busyForm(partner,async fd=>{await api('/api/admin/diamonds/partner','POST',{user_id:fd.get('user_id'),basis:fd.get('basis'),reason:fd.get('reason'),verified:fd.has('verified')});toast('파트너 검증 결과를 반영했어요.');await render();});
 const streams=document.getElementById('stream-finalize-form');if(streams)streams.onsubmit=busyForm(streams,async fd=>{const b=Object.fromEntries(fd);for(const k of ['paidKRW','refundedKRW','paymentFeeKRW','taxKRW'])b[k]=Number(b[k]);b.verified=fd.has('verified');await api('/api/admin/diamonds/streams','POST',b);toast('유효 재생 기준으로 다이아를 확정했어요.');await render();});
 for(const f of document.querySelectorAll('.diamond-reverse-form'))f.onsubmit=busyForm(f,async fd=>{if(!confirm('이 수익을 제외하고 다이아와 파트너 실적을 차감할까요?'))return;await api('/api/admin/diamonds/reverse','POST',{id:f.dataset.id,reason:fd.get('reason')});toast('해당 수익을 제외했어요.');await render();});
}
function partnerAdminHTML(d){return heading('파트너 · 다이아 관리','확정된 실적을 검증하고 수익을 반영해요.')+`<a class="text-link" href="#admin">정산 관리로</a><div class="surface earnings"><h2>창작자 검증</h2><div class="table-scroll"><table class="earnings-table"><thead><tr><th>창작자</th><th>등급</th><th>인정 실적</th><th>검증</th></tr></thead><tbody>${d.people.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.email)}</small></td><td>${p.tier==='partner'?'공식 파트너':'일반'}</td><td>${number(p.eligible_krw)}원</td><td>${p.review_required?'승급 검증 대상':p.qualified?'조건 충족':'누적 중'}</td></tr>`).join('')}</tbody></table></div><form id="partner-review-form" class="upload-form"><label class="form-field">창작자<select name="user_id">${d.people.map(p=>`<option value="${esc(p.user_id)}">${esc(p.name)} · ${esc(p.email)}</option>`).join('')}</select></label><label class="form-field">처리<select name="basis"><option value="earned">누적 100만 원 검증 승급</option><option value="special">운영자 특별 선정</option><option value="revoke">파트너 해제</option></select></label><label class="form-field">선정·검증 사유<input name="reason" required maxlength="500"></label><label class="checkbox-line"><input type="checkbox" name="verified" required>환불·취소·부정 재생·자가 후원을 제외하고 검증했습니다.</label><button class="primary-button">검증 결과 반영</button><p class="form-error" role="alert"></p></form></div><details class="surface earnings"><summary>스트리밍 정산 확정</summary><p>실제 결제·환불·세금·수수료 증빙을 확인한 금액만 입력하세요. 순매출의 50%를 유효 재생 수에 따라 원곡 창작자에게 배분합니다. 커버 재생도 원곡자에게 반영됩니다. 확정한 달은 중복 반영되지 않습니다.</p><form id="stream-finalize-form" class="upload-form"><label class="form-field">정산 월<input type="month" name="period" required></label>${[['paidKRW','총 결제액'],['refundedKRW','환불액'],['paymentFeeKRW','실제 결제 수수료'],['taxKRW','세금']].map(([key,label])=>`<label class="form-field">${label} (원)<input name="${key}" type="number" min="0" step="1" required></label>`).join('')}<label class="form-field">정산 증빙 참조<input name="evidence" required maxlength="500"></label><label class="checkbox-line"><input name="verified" type="checkbox" required>증빙과 비정상 재생 제외 여부를 검증했습니다.</label><button class="primary-button">다이아 확정</button><p class="form-error" role="alert"></p></form></details><details class="surface earnings"><summary>최근 확정 수익 · 부정 수익 제외</summary><form id="gift-exclude-form" class="upload-form"><h3>환불·비정상 선물 제외</h3><label class="form-field">선물 ID<input name="gift_id" required maxlength="100"></label><label class="form-field">증빙·제외 사유<input name="reason" required maxlength="500"></label><button class="small-button">선물 수익 제외</button><p class="form-error" role="alert"></p></form>${d.credits.map(c=>`<form class="diamond-reverse-form upload-form" data-id="${esc(c.id)}"><p>${esc(c.name)} · ${esc(c.period)} · ${c.kind==='gift'?'선물':'재생'} · ${diamondNumber(c.amount_mw/100000)}다이아</p><label class="form-field">제외 사유<input name="reason" required maxlength="500" placeholder="환불·취소·자가 후원·부정 재생 증빙"></label><button class="small-button">이 수익 제외</button><p class="form-error" role="alert"></p></form>`).join('')}</details>`;}
